(23, 'project', 2, 1, 12, 3, 'Energypac Power Generation', 'Square Pharmaceuticals', NULL, 'Bangladesh Textile Mills', '<p>Shakil is a dedicated professional from Netrokona, Bangladesh. Currently working as a HR Manager at Brain Station 23. Passionate about technology and innovation, with 3 years of experience in the field.</p>', '[\"uploads\\/project\\/img_6a365f950a125_1781948309.webp\",\"uploads\\/project\\/img_6a365f950a46c_1781948309.webp\"]', '[\"uploads\\/project\\/img_6a365f950a838_1781948309.webp\",\"uploads\\/project\\/img_6a365f950ac19_1781948309.webp\"]', '<p>Shakil is a dedicated professional from Netrokona, Bangladesh. Currently working as a HR Manager at Brain Station 23. Passionate about technology and innovation, with 3 years of experience in the field.</p>', '[{\"key\": \"Size (Sq.ft)\", \"value\": \"Shakil আহমেদ\"}]', '[]', NULL, 'BRAC Bangladesh', 'uploads/project/img_6a365f950699b_1781948309.webp', '[\"uploads/project/img_6a365f9509934_1781948309.webp\", \"uploads/project/img_6a365f9509d17_1781948309.webp\"]', NULL, NULL, NULL, '2025-06-15 10:30:00', NULL, 'Bangladesh', 'Shakil is a dedicated professional from Narayanganj, Bangladesh. Currently working as a Sales Representative at Banglalink Digital Communications. Passionate about technology and innovation, with 2 years of experience in the field.', NULL, 7, 0, 3, NULL, NULL, '2025-06-15 04:30:00', NULL, '2026-06-20 03:38:29', '2026-06-20 03:38:29'),
